    suspend fun fetch(): List<CctvCamera> = CAMS.map { c ->
        CctvCamera(
            id = c.id,
            lat = c.lat,
            lng = c.lng,
            name = c.name,
            city = c.city,
            country = c.country,
            feedUrl = c.liveId?.let { id -> "https://cdn.skylinewebcams.com/$id.jpg" },
            externalUrl = c.externalUrl,
            source = "SkylineWebcams",
        )
    }
